window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["15"]={"https://www.gov.uk/foreign-travel-advice/brazil":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"729ece0257ba9c602d967744d31302831ab416c597737609e7a5e6079b12a8c4","read":"https://www.gov.uk/api/content/foreign-travel-advice/brazil","bytes":76842,"x":"fulltext v1","title":"Brazil travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-18T15:00:20+00:00","mod":"2026-11-17T13:27:42+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"hs","s":["Amazonas State"]},{"k":"p","s":["FCDO advises against all but essential travel to the following river areas towards the west of Amazonas State:"]},{"k":"li","s":["along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State"]},{"k":"li","s":["along any part of the Itaquaí River in Amazonas State"]},{"k":"li","s":["along any part of the Japurá River or its tributaries in Amazonas State"]},{"k":"li","s":["along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State"]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/brazil/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/brazil/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Brazil’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Brazil set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Brazilian Embassy in the UK","https://www.gov.br/mre/pt-br/embaixada-londres"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Brazil, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["British-Brazilian dual nationals"]},{"k":"p","s":["Brazilian immigration authorities often require dual British-Brazilian nationals visiting Brazil to travel on Brazilian (rather than British) passports."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Brazil without a visa for up to 90 days for tourism."]},{"k":"p","s":["If you want to extend your tourist visa, contact the ",["Federal Police","https://www.gov.br/pf/pt-br/assuntos/imigracao"]," (in Portuguese) before your visa expires."]},{"k":"p","s":["For more information about visas, contact the ",["Brazilian Consulate in London","https://www.gov.br/mre/pt-br/consulado-londres/consulate-general"],"."]},{"k":"p","s":["If you overstay your visa, you’ll face a daily fine. You have the option to pay this fine either when you leave Brazil or during your next visit."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure the border control officer puts a stamp in your passport. If it is not stamped, you may be fined when you leave."]},{"k":"p","s":["Read about ",["passport stamping if you live in Brazil","https://www.gov.br/pf/pt-br/assuntos/passaporte/ajuda/duvidas_/caderneta/caderneta-carimbo-no-passaporte"]," (in Portuguese)."]},{"k":"h","s":["Travelling with children"]},{"k":"hs","s":["Children with dual British-Brazilian citizenship"]},{"k":"p","s":["British-Brazilian dual nationals under the age of 18 who are travelling without both parents or legal guardians need authorisation from both parents or legal guardians to travel in Brazil or leave the country. Read more about the ",["formal travel authorisation process for Brazilian minors","https://www.gov.br/mre/pt-br/consulado-londres/brazilian-minor-children-travel/travel-consent-for-brazilian-minor-children"]," and the ",["frequently asked questions","https://www.gov.br/mre/pt-br/consulado-londres/brazilian-minor-children-travel/frequently-asked-questions"],"."]},{"k":"hs","s":["Children who are not dual British-Brazilian nationals"]},{"k":"p","s":["Families of non-Brazilian under-18s travelling through Brazil without one or both parents should follow the instructions for dual British-Brazilian under-18s. Make sure the under-18 or their travelling companion also carries the original or notarised copy of the under-18’s birth certificate. Contact the ",["Brazilian Consulate in London","https://www.gov.br/mre/pt-br/consulado-londres/consulate-general"]," for more information."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Brazil guide","https://travelhealthpro.org.uk/country/34/brazil#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Brazil","https://www.gov.br/mre/pt-br/consulado-londres/useful-information/visiting-brazil#goods"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Brazil"]},{"k":"p","s":["If you are bringing cash or travellers cheques into Brazil with a value of 10,000 US dollars or more, you will need to ",["declare it online","https://www.gov.br/mre/pt-br/consulado-londres/useful-information/visiting-brazil"],"."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Brazil","https://www.gov.uk/foreign-travel-advice/brazil/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Brazil"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Brazil."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreigners. You should remain aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities. Targets could include:"]},{"k":"li","s":["crowded places"]},{"k":"li","s":["public gatherings"]},{"k":"p","s":["On 13 November 2024, two explosions occurred at the Praça dos Três Poderes in central Brasilia. You should exercise caution around major sites in large Brazilian cities."]},{"k":"h","s":["Protests and civil unrest"]},{"k":"p","s":["Protests, demonstrations and strikes may take place in cities across Brazil. Even peaceful events can become confrontational and may turn violent. Police have used rubber bullets and tear gas to disperse protesters."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid political rallies, protests and demonstrations"]},{"k":"li","s":["monitor local media for updates"]},{"k":"li","s":["follow the instructions of local authorities"]},{"k":"p","s":["If you encounter a protest or demonstration, or feel uncomfortable in a large crowd, leave the area as soon as it is safe to do so."]},{"k":"h","s":["Favelas"]},{"k":"p","s":["Favelas (‘slum’ or ‘shanty town’) are urban neighbourhoods of high-density informal housing. They exist in all major Brazilian cities and can border areas used by tourists and visitors."]},{"k":"p","s":["The security situation in many favelas is unpredictable and can be dangerous. Tourists have been shot after accidentally entering favelas."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid all favelas, including favela tours marketed to tourists and any accommodation, restaurants or bars advertised as being within a favela"]},{"k":"li","s":["if you’re using GPS navigation, make sure the suggested route does not take you into a favela"]},{"k":"p","s":["If you’re unsure about a location, check with your hotel or the local authorities."]},{"k":"h","s":["Crime"]},{"k":"p","s":["If you’re the victim of crime, contact the local police number 190 or the nearest British embassy or consulate."]},{"k":"p","s":["Read our guidance ",["if you’re the victim of a crime abroad","https://www.gov.uk/guidance/victim-of-crime-abroad"],"."]},{"k":"hs","s":["Theft and robbery"]},{"k":"p","s":["Robberies are common in many cities, particularly on buses. Thieves target mobile phones, particularly between 4pm and 9pm. Attackers may be armed and under the influence of drugs. Do not resist attackers. If threatened, hand over your valuables without resistance."]},{"k":"p","s":["Thefts are particularly common on public beaches and include ‘arrastões’ where large groups of thieves run through an area of the beach grabbing possessions. Keep your belongings close and avoid taking valuables to the beach. Do not go on to city beaches after dark."]},{"k":"p","s":["Pickpocketing is common."]},{"k":"p","s":["Criminals target large-scale celebrations in Brazil, such as the Carnival in major cities. Be aware of your personal security and surroundings. Be cautious about proposals from strangers that take you away from public areas."]},{"k":"p","s":["To reduce your risk:"]},{"k":"li","s":["avoid wearing expensive jewellery and watches"]},{"k":"li","s":["avoid carrying large sums of money"]},{"k":"li","s":["avoid using a mobile phone in the street"]},{"k":"li","s":["leave your passport and valuables in a safe place"]},{"k":"hs","s":["Criminal Kidnapping"]},{"k":"p","s":["Short-term opportunistic kidnapping (called ‘express kidnapping’) can happen. Victims have been kidnapped for a short period of time and driven to an ATM to withdraw money before being abandoned. Express kidnappers may use violence."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Bank and credit card scams are common in Brazil, including card cloning from ATMs and in shops. Payment machine and beach vendor scams have also been reported, particularly in busy tourist areas, where incorrect amounts may be charged or visitors may be overcharged. Always keep sight of your card and check the amount displayed on the payment terminal before paying. Do not use an ATM if you notice anything suspicious. Ask for a receipt, regularly monitor your bank statements, and contact your bank immediately if you notice any discrepancies."]},{"k":"p","s":["If you withdraw cash at an ATM and the cash has pink marks on it, speak to the bank (or police) straight away to get it changed. It may have been marked as damaged or counterfeit."]},{"k":"p","s":["Dating apps have been used by criminals to target foreign nationals in Brazil, leading to spiking of drinks, robbery and theft from bank accounts. Exercise caution when engaging with such apps, buy and keep hold of your own drinks, share your plans with friends or family, and be vigilant of your belongings including your mobile phone."]},{"k":"hs","s":["Sexual assault and drink spiking"]},{"k":"p","s":["Rape and other sexual offences against tourists are not common, but there have been attacks against both women and men. Some have involved date rape drugs. Buy your own drinks and keep them in sight."]},{"k":"p","s":["If you begin to feel strange, sick or drunk after only a couple of drinks, tell a trusted friend or security staff. They should take you to a safe place, such as your hotel room or a hospital. You can phone the local police, a hospital or the nearest British embassy or consulate for advice."]},{"k":"p","s":["Read our advice on what to do if you have been ",["raped, sexually assaulted or drugged abroad","https://www.gov.uk/guidance/victim-of-rape-and-sexual-assault-abroad"],"."]},{"k":"hs","s":["Methanol poisoning"]},{"k":"p","s":["There have been deaths and cases of serious illness caused by alcoholic drinks containing methanol in Brazil. Take care when buying spirit-based drinks, including gin, vodka and whisky."]},{"k":"p","s":["Even small amounts of methanol can kill. It is not possible to identify methanol in alcoholic drinks by taste or smell. See ",["Travel Aware Drink Spiking and Methanol Poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," for information about how to reduce the risks."]},{"k":"p","s":["Seek urgent medical attention if you or someone you are travelling with show the ",["signs of methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," after drinking."]},{"k":"hs","s":["Child sexual abuse"]},{"k":"p","s":["There are cases of sexual abuse of children in Brazil. All sexual activity with children (people under the age of 18) is illegal, regardless of the age of consent locally. If you commit sex offences against children abroad, you can be prosecuted in the UK."]},{"k":"hs","s":["Parental child abduction"]},{"k":"p","s":["Parental child abduction is not common but can happen in Brazil. Dial 190 to report a missing child or go to the nearest police station. Read the ",["guidance on international parental child abduction","https://www.gov.uk/government/publications/international-parental-child-abduction"]," if your child may be at risk of this."]},{"k":"hs","s":["Carjacking"]},{"k":"p","s":["Theft from cars is common. Keep valuables out of sight."]},{"k":"p","s":["Carjacking can happen, particularly on major roads and in tunnels. To reduce your risk:"]},{"k":"li","s":["approach your car with your keys in your hand so you can get into your car quickly"]},{"k":"li","s":["keep doors locked and windows closed"]},{"k":"li","s":["take particular care at traffic lights"]},{"k":"li","s":["be cautious of people approaching to ask for information, especially at night"]},{"k":"li","s":["if driving at night outside the city, avoid stopping at the roadside – if you must stop, try to stop in a well-lit area"]},{"k":"hs","s":["Organised crime and militias"]},{"k":"p","s":["Organised crime groups and militias operate in Brazil, including in many cities. Armed incidents, including police operations, can occur with little warning. Be aware of your surroundings. Avoid favelas and suburbs where possible."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry a copy of your passport and another form of photo ID if you have one."]},{"k":"hs","s":["Illegal drugs and trafficking scams"]},{"k":"p","s":["Drug trafficking is widespread in Brazil. Bringing drugs in to or out of Brazil in any quantity is illegal and the penalties are severe."]},{"k":"p","s":["You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["British nationals have been targeted through email scams where fraudsters offer a financial reward for travelling to Brazil, where they are then asked to carry items in to or out of Brazil, including to the UK. These items are often illegal drugs. Anyone caught will face detention for drug trafficking, regardless of the circumstances."]},{"k":"p","s":["Airports in Brazil have excellent technology and security for detecting illegal items, including cannabis. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Electronic smoking devices"]},{"k":"p","s":["All electronic cigarettes and vaping devices are illegal in Brazil, including refills, parts and accessories."]},{"k":"p","s":["Customs officials have the authority to confiscate any vape products found in travellers’ luggage (both checked in and carry on) during inspections."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["There is no legislation against same-sex sexual activity in Brazil. Same-sex marriage is legal and LGBT+ couples have equal rights in law."]},{"k":"p","s":["São Paulo, Rio de Janeiro and other cities hold Pride events, which attract large numbers. These events are usually very peaceful."]},{"k":"p","s":["Brazil is generally tolerant. However, Brazilian society is quite conservative, particularly outside the larger towns and cities. There are reports of discrimination, violence and harassment against the LGBT+ community. Urban areas are usually more accepting."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Strong currents can be a danger off some beaches. Get local advice before going in the water. Pay attention to warning flags and the location of lifeguards if present on the beach."]},{"k":"p","s":["Shark attacks are a danger, particularly on the beaches around Recife in north-east Brazil. Pay attention to warning signs and consult lifeguards if unsure. Sharks have been known to attack in waist-deep water and deaths have occurred."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Brazil, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Brazil. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["After 180 days, you need to apply for a Brazilian driving licence."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Brazil has a high road accident rate. Driving standards are poor. Take care on the roads and avoid riding bicycles. In many rural areas, roads are in poor condition away from the main highways. Bus and coach crashes are frequent."]},{"k":"p","s":["Immediately report all accidents to the police: call 190 or go to a police station."]},{"k":"p","s":["Contact the police if vehicles are obstructing traffic and you need help."]},{"k":"hs","s":["Drink-driving"]},{"k":"p","s":["Drink-driving is a serious offence in Brazil and checkpoints are often set up. If you’re caught driving under the influence of alcohol, you will be prosecuted. Penalties range from fines and a suspension from driving for 12 months, to up to 3 years in prison."]},{"k":"hs","s":["Taxi travel"]},{"k":"p","s":["There have been reports of express kidnappings, assaults and robberies from unlicensed taxis, including in cars using fraudulent ride-hailing accounts, such as Uber. Do not hail taxis on the street. There are authorised taxi booths at most airports in Brazil."]},{"k":"p","s":["Ride-hailing apps, such as Uber, are widely available in Brazil. Be wary of unregulated drivers posing as ride-hailing app drivers, especially at airports."]},{"k":"p","s":["Make sure you:"]},{"k":"li","s":["book through the official app"]},{"k":"li","s":["wait in a safe location until your vehicle arrives, including at designated pick-up areas at airports"]},{"k":"li","s":["check the vehicle registration and driver details match"]},{"k":"li","s":["are alert to any diversions or change in destination on the app"]},{"k":"li","s":["do not display your phone or valuables"]},{"k":"li","s":["use available safety features such as trip tracking and location sharing"]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["If you have been a victim of a passport theft and you need to fly to Brasilia, São Paulo or Rio de Janeiro for consular services, you can travel on domestic flights with a valid photo ID or a police report."]},{"k":"p","s":["Check whether your tour operator has concerns about airlines in Brazil."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["There have been armed and unarmed attacks on merchant vessels, including British flag vessels off the Brazilian coast and in some Brazilian ports."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["There have been instances of theft and robbery on the rail network, including urban metro rail networks. Avoid wearing expensive jewellery and watches or using a mobile phone during train travel."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["El Niño 2026-2027"]},{"k":"p","s":["A strong El Niño climate event is expected from late 2026 until early 2027. This may increase the risk of heavy rainfall, flooding and landslides in southern Brazil, and drought, high temperatures and wildfires in northern and north-eastern Brazil. Conditions can change quickly."]},{"k":"p","s":["Sign up for local ",["Civil Defence disaster alerts","https://www.gov.br/pt-br/servicos/solicitar-cadastro-para-recebimento-de-avisos-e-alertas-de-desastres"]," and monitor ",["weather warnings and forecasts","https://portal.inmet.gov.br/"],"."]},{"k":"hs","s":["Heavy rainfall"]},{"k":"p","s":["The rainy season runs from November until March in the south and south-east of Brazil (including Rio de Janeiro) and from April until July in the north-east of Brazil. However heavy rainfall and flooding can also occur outside of the designated rainy seasons, in any region of the country."]},{"k":"p","s":["Heavy rainfall often disrupts infrastructure, particularly in rural areas. Flash floods and landslides are common in regions where mountains are close to the coast, such as Rio de Janeiro. This includes in tourist areas. People have drowned when swept away in fast flowing water. Cars and buses have been caught in landslides, resulting in deaths."]},{"k":"p","s":["Monitor local media and follow local authority warnings which are displayed on digital street signs and sent to hotels and hostels. Follow any instructions given by the local authorities. Avoid travelling on the road during heavy rain. If you are outside when the rain starts, avoid walking in flooded areas, and do not cross fast flowing water, however shallow you think it is."]},{"k":"hs","s":["Forest fires"]},{"k":"p","s":["Forest fires are common from May to September, especially during July and August due to the dry season. They are highly dangerous and unpredictable. Check the latest alerts and ",["weather forecast","https://portal.inmet.gov.br/"]," (in Portuguese) and follow the advice of local authorities if you’re considering travelling to affected areas."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Brazil. It only covers regions where FCDO has specific advice. You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/brazil"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security"],"."]},{"k":"p","s":["You should monitor local media and follow the guidance of local authorities when travelling in remote areas."]},{"k":"h","s":["Amazonas State"]},{"k":"hs","s":["River travel"]},{"k":"p","s":["FCDO advises against all but essential travel:"]},{"k":"li","s":["along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State"]},{"k":"li","s":["along any part of the Itaquaí River in Amazonas State"]},{"k":"li","s":["along any part of the Japurá River or its tributaries in Amazonas State"]},{"k":"li","s":["along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State"]},{"k":"p","s":["There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity. Armed groups, including pirates and drug traffickers, travel by the river routes in the Amazonas state where is there is low presence of police and local authorities."]},{"k":"h","s":["Rio de Janeiro"]},{"k":"p","s":["The most common incidents affecting British nationals in Rio de Janeiro are thefts and pickpocketing around:"]},{"k":"li","s":["Copacabana beach"]},{"k":"li","s":["Ipanema beach"]},{"k":"li","s":["Lapa"]},{"k":"li","s":["Santa Teresa"]},{"k":"p","s":["Tourists have reported armed robberies on the Corcovado walking trail to the Christ the Redeemer statue. See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["São Paulo"]},{"k":"p","s":["The most common incidents affecting British nationals in São Paulo are thefts or pickpocketing around:"]},{"k":"li","s":["Avenida Paulista"]},{"k":"li","s":["the historical downtown area"]},{"k":"li","s":["the red light districts located on Rua Augusta (north of Avenida Paulista)"]},{"k":"li","s":["Catedral da Sé"]},{"k":"li","s":["Praça da República"]},{"k":"li","s":["the Estacao de Luz metro area (where Cracolandia is located)"]},{"k":"li","s":["Pinheiros"]},{"k":"p","s":["See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["Brasilia"]},{"k":"hs","s":["Theft"]},{"k":"p","s":["In Brasilia, the central bus station area has a lot of incidents of theft. Theft from pedestrians also happens across the city, especially in the central and southern commercial centres. Take particular care at these locations. See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["North-east Brazil"]},{"k":"hs","s":["Theft"]},{"k":"p","s":["The most common incidents affecting British nationals in north-east Brazil are theft from hotel and motel rooms and muggings. Reduce the risk of being mugged by avoiding quiet or deserted areas and by using taxis after sunset instead of walking. See our advice on ",["Theft and robbery","https://www.gov.uk/foreign-travel-advice/brazil/safety-and-security#theft-and-robbery"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 192 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccination recommendations for Brazil","https://travelhealthpro.org.uk/country/34/brazil#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Brazil","https://travelhealthpro.org.uk/country/34/brazil"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["dengue"]},{"k":"li","s":["chikungunya"]},{"k":"li","s":["oropouche"]},{"k":"li","s":["high UV levels"]},{"k":"p","s":["Altitude sickness is a risk in parts of Brazil. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["If you’re taking medication, bring a prescription or letter from your doctor confirming your need to carry the medication. Bring enough to last your whole trip, as some medicines may not be available locally. Counterfeit drugs can be an issue, so it’s better to travel with your own supplies."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Brazil"]},{"k":"p","s":["Foreign nationals are entitled to emergency medical treatment in Brazilian public hospitals. Public hospitals in Brazil, especially in major cities, tend to be overcrowded and there’s often a long wait for a bed and a lack of medication. Private hospitals will not accept you unless you can show evidence of enough money or insurance to cover your treatment."]},{"k":"p","s":["FCDO has a list of ",["medical providers in Brazil","https://www.gov.uk/government/publications/list-of-doctors--2"]," where some staff will speak English."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Brazil","https://www.gov.uk/guidance/living-in-brazil#healthcare-in-brazil"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Brazil"]},{"k":"p","s":["Ambulance: 192"]},{"k":"p","s":["Fire: 193"]},{"k":"p","s":["Police: 190 or 911"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=brazil"]," and ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=brazil"]," in Brazil"]},{"k":"li","s":["dealing with a ",["death in Brazil","https://www.gov.uk/government/publications/brazil-bereavement-packinformation"]]},{"k":"li","s":["being ",["arrested or imprisoned in Brazil","https://www.gov.uk/government/publications/brazil-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of rape or sexual assault in Brazil","https://www.gov.uk/government/publications/rape-and-sexual-assault-in-brazil-local-guide"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/brazil/british-embassy-brasilia"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/brazil/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Brazil","https://www.gov.uk/government/publications/overseas-business-risk-brazil"]," on how to manage political, economic, and business security-related risks."]}],"chars":24831,"change":"New information about the risk of extreme weather due to the El Niño climate event (‘Safety and security’ page)."},"https://www.gov.uk/foreign-travel-advice/canada":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"9d15c591c2c4e3f0c481bd6b82b04cbc32c061dcbcd1adada952f5b3baaa497d","read":"https://www.gov.uk/api/content/foreign-travel-advice/canada","bytes":66581,"x":"fulltext v1","title":"Canada travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-18T00:00:00+00:00","mod":"2026-06-02T17:02:41+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/canada/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Canada’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Canada set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Canadian High Commission in the UK","https://www.international.gc.ca/country-pays/united_kingdom-royaume_uni/london-londres.aspx?lang=eng"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Canada, your passport must be valid for the length of your planned stay."]},{"k":"p","s":["If you’re travelling through another country on your way to or from Canada, check the entry requirements for that country. Many countries will only allow entry if you have at least 6 months validity remaining on your passport."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["To enter or transit through Canada, most people need a visa or an Electronic Travel Authorization (eTA) – not both."]},{"k":"p","s":[["Check if you need a visa or an eTA online","https://ircc.canada.ca/english/visit/visas.asp"],"."]},{"k":"p","s":["You do not need a visa for short visits (normally up to 6 months). You may need an eTA instead."]},{"k":"p","s":["You do not need an eTA, if you are:"]},{"k":"li","s":["arriving by land and sea – you must have ",["acceptable travel documents and ID","https://www.cbsa-asfc.gc.ca/travel-voyage/td-dv-eng.html"]]},{"k":"li","s":["a British-Canadian dual national – you must have a valid Canadian passport"]},{"k":"p","s":["See ",["Canada’s entry requirements","https://www.canada.ca/en/immigration-refugees-citizenship/services/visit-canada/entry-requirements-country.html"]," for full details of eTA and visa requirements."]},{"k":"p","s":["Contact the ",["Canadian High Commission in the UK","https://www.international.gc.ca/country-pays/united_kingdom-royaume_uni/london-londres.aspx?lang=eng"]," if you are unsure about visa requirements or your eligibility to enter the country, for example, if you have a criminal record or have been arrested."]},{"k":"hs","s":["Checks at border control"]},{"k":"p","s":["Canadian border officials may ask you to show a return or onward ticket and proof that you have sufficient funds to support yourself for the duration of your stay, even if you are staying with family or friends."]},{"k":"hs","s":["Visas for permanent residence, study or work"]},{"k":"p","s":["See information on ",["visas for permanent residence, study or work in Canada","https://www.canada.ca/en/services/immigration-citizenship.html"],"."]},{"k":"h","s":["Ebola"]},{"k":"p","s":["As a public health measure, Canada has introduced temporary border measures for travellers arriving from regions affected by the Ebola outbreak."]},{"k":"p","s":["Canada is suspending certain immigration documents for residents of the Democratic Republic of 4Congo, Uganda and South Sudan until August 28, 2026."]},{"k":"p","s":["Canadian citizens, permanent residents, and foreign nationals entering Canada who, in the previous 21 days, have been in the Democratic Republic of the Congo, Uganda or South Sudan will be given a health assessment upon arrival. Those who do not have symptoms will have to quarantine for 21 days. If they do not have a place where they can quarantine safely, they will be provided with an appropriate location. Travellers who have symptoms will be isolated at a hospital for further assessment. These measures are being implemented under the Quarantine Act. This border measure will be in place until August 29, 2026."]},{"k":"p","s":["The World Health Organisation (WHO) has ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"],"."]},{"k":"p","s":["Check the ",["Government of Canada’s official website for more information","https://www.canada.ca/en/public-health/services/diseases/ebola/border-measures.html"],"."]},{"k":"hs","s":["Transiting through Canada"]},{"k":"p","s":["If you are travelling through Canada (transiting) by air, you must have an eTA or a transit visa."]},{"k":"p","s":["If you have questions, contact:"]},{"k":"li","s":["your airline"]},{"k":"li","s":[["Immigration, Refugees and Citizenship Canada","https://www.canada.ca/en/immigration-refugees-citizenship.html"]]},{"k":"li","s":["your nearest Canadian high commission, embassy or consulate"]},{"k":"p","s":[["Find out more about transiting Canada","https://www.canada.ca/en/immigration-refugees-citizenship/services/visit-canada/transit.html"],"."]},{"k":"hs","s":["Visa and eTA scams"]},{"k":"p","s":["Some unauthorised websites charge for submitting visa applications. These websites are not associated with the Canadian government."]},{"k":"p","s":["You can ",["check your eTA status online with the Canadian government","https://onlineservices-servicesenligne.cic.gc.ca/eta/applicationQuery?lang=en"],". If it has been 72 hours since you applied, and you have not received confirmation of your application, ",["complete an enquiry form","https://secure.cic.gc.ca/enquiries-renseignements/canada-case-cas-eng.aspx"],"."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["If a child travels alone or with only one parent or legal guardian, they should carry a letter of consent from the non-travelling parents or guardians. Immigration officers have the right to question children using simple and appropriate language to see if there are any concerns about child abduction."]},{"k":"p","s":["For more information, check with the ",["Canadian High Commission in the UK","https://www.international.gc.ca/country-pays/united_kingdom-royaume_uni/london-londres.aspx?lang=eng"]," or the Canada Border Services Agency."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Canada guide","https://travelhealthpro.org.uk/country/41/canada#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Canada","https://travel.gc.ca/returning/customs/what-you-can-bring-home-to-canada"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["The Canadian authorities will confiscate banned food products and you could get a fine. For more information, see ",["importing food, plants or animals to Canada","https://inspection.canada.ca/importing-food-plants-or-animals/eng/1573836795867/1573836899201"],"."]},{"k":"p","s":["If you visit a farm or have contact with wild animals before entering Canada, and plan to visit a farm during your stay, you must declare this on your Customs Declaration Card. For more information, see ",["biosecurity at the Canadian border","https://inspection.canada.ca/animal-health/terrestrial-animals/biosecurity/general-public/border/eng/1344754371697/1344754930771"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Canada"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Canada."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals. You should remain aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"p","s":["Recent attacks include:"]},{"k":"li","s":["in 2023, one person stabbed and injured in Surrey, British Columbia"]},{"k":"li","s":["in 2021, 4 people killed and one injured by a vehicle in London, Ontario"]},{"k":"p","s":["See the Canadian government’s national terrorism threat level."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Take precautions to protect yourself from petty crime, including:"]},{"k":"li","s":["not leaving your bag or luggage unattended"]},{"k":"li","s":["keeping luggage out of sight in cars"]},{"k":"li","s":["keeping valuables and passport in a safe location"]},{"k":"li","s":["leaving copies of important documents with family and friends in the UK"]},{"k":"li","s":["carrying a copy of your passport for ID"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and cannabis"]},{"k":"p","s":["Illegal drugs carry severe penalties. You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Recreational cannabis is legally available in Canada. ",["Laws vary depending on the province or territory you are visiting","https://www.canada.ca/en/health-canada/services/drugs-medication/cannabis/laws-regulations/provinces-territories.html"],". It is illegal to take cannabis across the Canadian border without a permit or exemption authorised by Health Canada. Those who attempt to take cannabis out of Canada without the relevant permit face arrest."]},{"k":"p","s":["Airports in Canada have excellent technology and security for detecting illegal items, including cannabis. This is also used to scan the baggage of transiting passengers."]},{"k":"p","s":["See the Canadian Border Services Agency website for more information."]},{"k":"hs","s":["Wildlife"]},{"k":"p","s":["If you are hiking or camping, be considerate and cautious of local wildlife. You should:"]},{"k":"li","s":["take all rubbish with you including food items to avoid attracting animals to your site"]},{"k":"li","s":["be careful around animals with nearby young or nests – they may be aggressive when protecting their territory"]},{"k":"li","s":["research the region to learn about the local wildlife"]},{"k":"li","s":["take particular care if you’re in an area where bears have been sighted"]},{"k":"li","s":["keep a safe distance from any wildlife including marine animals and birds"]},{"k":"li","s":["follow park regulations"]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["See advice on ",["visitor safety","https://parks.canada.ca/voyage-travel/securite-safety"]," when planning outdoor activities and adventure tourism in Canada, and on ",["preparing for winter sports abroad","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Canada, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["See ",["driving in Canada","https://www.canada.ca/en/immigration-refugees-citizenship/services/new-immigrants/new-life-canada/driving.html"]," for information on traffic and safety laws. Laws vary between provinces and territories, including:"]},{"k":"li","s":["whether you are allowed to turn right on a red light"]},{"k":"li","s":["driving licence requirements – you may need to get an ",["international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]]},{"k":"p","s":["Take extra care when travelling on country roads and watch out for wild animals. For more information on road conditions and road safety, see ",["Transport Canada","https://tc.canada.ca/en"],", the Canadian Automobile Association and Travel Canada."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"hs","s":["Driving in winter"]},{"k":"p","s":["In winter, highways are often closed because of snowstorms and avalanches in Alberta, British Columbia and other provinces. Check local weather conditions on The Weather Network."]},{"k":"p","s":["Driving conditions can be dangerous, even when roads remain open during a winter storm. Take care, follow local restrictions or guidelines and make sure your vehicle has snow tyres and emergency supplies. See ",["winter driving advice","https://tc.canada.ca/en/road-transportation/stay-safe-when-driving/winter-driving"],", including vehicle preparation and using winter tyres."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Hurricanes"]},{"k":"p","s":["From July to November, hurricanes can affect coastal areas. Check the US National Hurricane Center, ",["Environment Canada","https://www.canada.ca/en/environment-climate-change.html"]," and The Weather Network websites for the latest weather conditions."]},{"k":"hs","s":["Avalanches"]},{"k":"p","s":["Avalanches can happen in mountainous regions, including Alberta and British Columbia. Always follow avalanche advice and stay away from closed trails. Follow the directions of local guides or instructors. For more information and avalanche news, see the ",["Canadian Avalanche Foundation","https://avalanche.ca/map"]," website."]},{"k":"hs","s":["Earthquakes and tsunamis"]},{"k":"p","s":["Familiarise yourself with safety procedures in the event of an earthquake or tsunami. The Canadian government has ",["information about emergency preparedness","https://www.getprepared.gc.ca/cnt/hzd/index-eng.aspx"],"."]},{"k":"hs","s":["Thunderstorms"]},{"k":"p","s":["Summer thunderstorms are frequent in most parts of Canada, particularly between April and September. They can damage property and threaten lives."]},{"k":"hs","s":["Winter storms"]},{"k":"p","s":["Winter storms, including freezing rain, blizzards and hail, are frequent in many parts of Canada, particularly from November to April. They can make driving conditions dangerous, damage property and threaten lives. Follow local warnings or news for details."]},{"k":"hs","s":["Tornadoes"]},{"k":"p","s":["Tornadoes can happen anywhere in Canada from May to September, but June to July is the peak season in:"]},{"k":"li","s":["southern Ontario"]},{"k":"li","s":["Alberta"]},{"k":"li","s":["south-eastern Quebec"]},{"k":"li","s":["southern Saskatchewan and Manitoba through to Thunder Bay"]},{"k":"li","s":["the interior of British Columbia and western New Brunswick"]},{"k":"p","s":["Follow instructions from Canadian officials or law enforcement. Check the US National Hurricane Center for weather updates."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires can start at any time, whatever the season, although there is particular risk of fire in the grasslands and forests of western Canada, as well as in forested areas of Quebec, Ontario and Nova Scotia, during the summer months."]},{"k":"p","s":["You should follow local warnings or news for details on the latest outbreaks. The Canadian Wildland Fire Information System shows ",["active wildfires and forecasts","https://cwfis.cfs.nrcan.gc.ca/home"],". You can also monitor wildfire smoke and air quality on ",["the Government of Canada’s website","https://www.canada.ca/en/services/health/healthy-living/environment/air-quality/wildfire-smoke.html"],"."]},{"k":"h","s":["Arctic travel"]},{"k":"p","s":["Parts of Canada are in the Arctic Circle, including some very remote areas of land and sea. Emergency medical assistance and search and rescue are limited in these areas. See ",["Arctic travel safety advice","https://www.gov.uk/guidance/arctic-travel-safety-advice"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel, check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 911 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Canada","https://travelhealthpro.org.uk/country/41/canada#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Canada","https://travelhealthpro.org.uk/country/41/canada#General_Information"],", including:"]},{"k":"li","s":["biting insects or ticks"]},{"k":"li","s":["mpox – also see ",["Canada’s Public Health Authority website","https://www.canada.ca/en/public-health/services/diseases/mpox/outbreak-update.html"]," which includes updates on mpox"]},{"k":"p","s":["Altitude sickness is a risk in parts of Canada, including skiing and hiking destinations in the Canadian Rockies such as Banff and Lake Louise. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["TravelHealthPro explains ",["best practice when travelling with medicines","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Canada"]},{"k":"p","s":["Medical treatment can be very expensive. There are no special arrangements for British visitors."]},{"k":"p","s":["For emergency healthcare, go to a hospital emergency room or a walk-in clinic."]},{"k":"p","s":["If you have dual British-Canadian citizenship, you may still have to pay for medical treatment if you do not meet provincial residency requirements for healthcare. Check with the relevant ",["province or territory health ministry","https://www.canada.ca/en/immigration-refugees-citizenship/services/new-immigrants/new-life-canada/health-care/universal-system.html#ministries"]," for more information."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Canada"]},{"k":"p","s":["Telephone: 911 (ambulance, fire, police)"]},{"k":"hs","s":["Coastguard maritime emergencies"]},{"k":"p","s":["Telephone: 1 800 463 4393"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Canada"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Canada"]," in Canada"]},{"k":"li","s":["dealing with a ",["death in Canada","https://www.gov.uk/government/publications/bereavement-information-for-canada"]]},{"k":"li","s":["being ",["arrested in Canada","https://www.gov.uk/government/publications/canada-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/canada/british-high-commission-ottawa"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/canada/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Canada","https://www.gov.uk/government/publications/overseas-business-risk-canada"]," on how to manage political, economic, and business security-related risks."]}],"chars":15775,"change":"Addition of information about entry requirements for those entering from Ebola-affected regions ('Entry requirements' page)."},"https://www.gov.uk/foreign-travel-advice/uruguay":{"r":"govuk","at":"2026-11-17T17:32Z","sha":"afd885af0599d15d7e711a33cd1bfa92da3cb003b2f80288513781504e5279e4","read":"https://www.gov.uk/api/content/foreign-travel-advice/uruguay","bytes":48075,"x":"fulltext v1","title":"Uruguay travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2025-12-10T13:00:39+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/uruguay/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Uruguay’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Uruguay set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Uruguayan Embassy in the UK","https://mapaconsular.mrree.gub.uy/index.php?option=com_zoo&task=item&item_id=250"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Uruguay, your passport must be valid for the duration of your stay and have at least one blank page for an entry stamp."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Uruguay without a visa for up to 90 days."]},{"k":"p","s":["To stay longer or take up residency in Uruguay, see ",["Dirección Nacional de Migración","https://migracion.minterior.gub.uy/"]," (in Spanish). For other information on entry regulations and living in Uruguay, contact the nearest Uruguayan Embassy."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["If they travel on a non-Uruguayan passport, alone or with just one parent, children aged 17 and under who live in Uruguay and non-resident children who have been in Uruguay for a year or more need ",["written permission (‘Permiso de Menor’) from non-accompanying parents to leave the country","https://www.gub.uy/tramites/permiso-menor-edad"]," (in Spanish). Children travelling on a Uruguayan passport do not need permission."]},{"k":"p","s":["The ",["Uruguay Ministry of the Interior","https://migracion.minterior.gub.uy/index.php/93-tramites/permiso-para-menor-de-edad/1365-permiso-de-menor"]," (in Spanish) has more information. If you’re in the UK, contact the ",["Uruguayan Embassy in the UK","https://mapaconsular.mrree.gub.uy/index.php?option=com_zoo&task=item&item_id=250"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Uruguay guide","https://travelhealthpro.org.uk/country/236/uruguay#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Uruguay","https://www.aduanas.gub.uy/innovaportal/v/2436/8/innova.front/hay-prohibiciones-al-ingreso-de-ciertos-articulos-por-parte-de-pasajeros.html"]," (in Spanish). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["It is illegal for visitors to import:"]},{"k":"li","s":["fruits, vegetables, animals or dairy products and their derivatives"]},{"k":"li","s":["flammable materials"]},{"k":"li","s":["alkaloids"]},{"k":"li","s":["narcotics"]},{"k":"li","s":["obscene objects"]},{"k":"li","s":["subversive or pornographic material"]},{"k":"p","s":["The authorities X-ray all baggage on arrival and may search it."]},{"k":"hs","s":["Taking money into Uruguay"]},{"k":"p","s":["You can bring in up to 10,000 US dollars or an equal amount in other currencies, precious metals or other monetary instruments (such as travellers cheques). You must declare amounts above this limit."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Uruguay"]},{"k":"p","s":["Although there’s no recent history of terrorism in Uruguay, attacks cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Street crime in Montevideo"]},{"k":"p","s":["Street crime happens in Montevideo, including:"]},{"k":"li","s":["bag-snatching and pickpocketing"]},{"k":"li","s":["mugging and robbery (sometimes armed)"]},{"k":"p","s":["You should:"]},{"k":"li","s":["keep valuables, spare cash and credit cards in a safe"]},{"k":"li","s":["take care using ATMs – where possible use machines not on the street (for example, in shopping centres or banks)"]},{"k":"li","s":["avoid carrying lots of cash or wearing expensive jewellery"]},{"k":"li","s":["consider carrying cash and bankcards in separate pockets and only carry the money you need"]},{"k":"p","s":["Keep away from isolated or poorly lit areas at night and avoid walking downtown or in the port area alone, especially at night and on weekends."]},{"k":"hs","s":["Theft from cars in Montevideo"]},{"k":"p","s":["Criminals regularly break into cars left on the street. Try to park in paid car parks or well-lit, busy areas."]},{"k":"p","s":["Always lock your car and avoid leaving valuables, luggage, personal documents and cash in the vehicle. Do not drive with bags or other valuables visible, especially on the front seat. Thieves can smash windows and grab valuables at traffic lights and junctions."]},{"k":"hs","s":["Crime outside Montevideo"]},{"k":"p","s":["Crime rates are generally lower in other parts of Uruguay, but still take usual precautions."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Money"]},{"k":"p","s":["You cannot always use credit cards outside of major towns. ATMs may not always accept UK debit cards."]},{"k":"hs","s":["Smoking and e-cigarette bans"]},{"k":"p","s":["It is illegal to smoke, including e-cigarettes, in enclosed public places such as restaurants, shopping centres and cinemas."]},{"k":"hs","s":["Marijuana"]},{"k":"p","s":["If they have registered with the Uruguayan government, it is legal for Uruguayan nationals or foreign nationals who have been resident for more than 2 years, to grow marijuana or buy it from registered pharmacies. However, it is illegal for tourists to do this."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex marriage is legal and there are anti-discrimination laws. Uruguay also recognises same-sex civil unions. It is common to see same-sex couples together in public, and hostility or discrimination towards LGBT+ visitors is rare."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Many beaches in Uruguay have lifeguards from December to March, although times vary across the country. Take care when swimming in rivers or the Atlantic Ocean. There can be currents, rocks and sandbanks with sudden descents."]},{"k":"p","s":["Beaches with lifeguards display coloured flags depending on the conditions:"]},{"k":"li","s":["green: good conditions for swimming"]},{"k":"li","s":["yellow: caution"]},{"k":"li","s":["red: danger – unsuitable conditions for swimming, rocks, uneven seabed or currents"]},{"k":"li","s":["red with green cross: danger – unsanitary conditions not suitable for swimming"]},{"k":"li","s":["black: thunderstorms – do not stay on the beach or near the coast"]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Uruguay, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Uruguay for the first 90 days after you arrive. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well. After 90 days, you must get a Uruguayan driving licence."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as 2 years of driving experience and holding an IDP."]},{"k":"p","s":["Driving laws include:"]},{"k":"li","s":["wearing a seatbelt in the front and back seats – children under 12 must wear a seatbelt and be in a child or booster seat"]},{"k":"li","s":["having a first aid kit in your car"]},{"k":"li","s":["using dipped headlights during the day"]},{"k":"p","s":["Uruguay is introducing electronic-tag-only tolls (in Spanish) – these require prepayment or a linked credit card with an electronic sticker fixed to your car. Rental cars will already have electronic tags. The rental company will charge you for any unpaid tolls."]},{"k":"p","s":["Drink-driving is a serious offence in Uruguay. If you are tested and found to have any alcohol in your system, you may get a fine and possible imprisonment, a driving suspension or a community work order."]},{"k":"p","s":["You will also get a fine if you’re found driving under the influence of drugs."]},{"k":"hs","s":["Road conditions"]},{"k":"p","s":["The main toll roads from Colonia del Sacramento to Montevideo and Punta del Este are in good condition and well-marked. However, serious road traffic accidents are common and often caused by poor road layout and speeding."]},{"k":"p","s":["The standard of roads in the rest of Uruguay varies. Roads may suddenly deteriorate, with potholes and uneven road surfaces. Take extra care, especially in bad weather or at night."]},{"k":"p","s":["Driving standards are poor and traffic is disorganised. Drivers may:"]},{"k":"li","s":["change lane and make unexpected turns without indicating"]},{"k":"li","s":["use hazard lights to stop in the middle of a lane, for example to drop someone off"]},{"k":"li","s":["ignore stop signs, traffic lights and speed limits"]},{"k":"p","s":["Motorbikes often go the wrong way down one-way streets – look both ways when crossing junctions."]},{"k":"p","s":["For information on transport regulations, see the ",["Montevideo municipality website","https://montevideo.gub.uy/areas-tematicas/sistema-de-transporte-metropolitano"]," (in Spanish)."]},{"k":"hs","s":["Bus terminal"]},{"k":"p","s":["The main bus terminal for long distance journeys is Tres Cruces (in Spanish). There are visible security patrols. Keep a close eye on your belongings."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["The Uruguay government usually issues warnings and updates on extreme weather through news channels and the press. ",["Sistema Nacional de Emergencias","https://www.gub.uy/sistema-nacional-emergencias/"]," (in Spanish) coordinates crisis responses."]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Occasional heavy storms can last 2 to 3 days and cause severe damage and flooding. Check for severe weather warnings from the ",["Uruguayan Institute of Meteorology","https://www.inumet.gub.uy/"]," (in Spanish). See ",["UK Met Office forecasts for Uruguay","https://www.metoffice.gov.uk/weather/world/uruguay"],"."]},{"k":"hs","s":["Forest fires"]},{"k":"p","s":["Forest fires can break out in the hottest months from December to March in dry areas. Extinguish cigarettes and fires appropriately. Call 911 to contact the fire brigade."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 911 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Uruguay","https://travelhealthpro.org.uk/country/236/uruguay#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Uruguay","https://travelhealthpro.org.uk/country/236/uruguay"],", including:"]},{"k":"li","s":["dengue"]},{"k":"li","s":["strong sun with high UV levels"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["If you have a pre-existing medical condition and take regular prescribed medication, take enough for your visit. You can find most medication in pharmacies in large cities, but medicine for complex treatment may be unavailable in smaller towns."]},{"k":"p","s":["You will need a prescription from a local doctor to get prescribed medication. All medication in pharmacies, whether prescribed or not, is stored behind the counter and must be asked for."]},{"k":"h","s":["Healthcare in Uruguay"]},{"k":"p","s":["Medical and dental treatment is expensive in Uruguay. Make sure you have adequate travel health insurance and accessible funds to cover the cost of medical treatment and repatriation."]},{"k":"p","s":["FCDO has a list of ",["medical providers in Uruguay","https://www.gov.uk/government/publications/uruguay-list-of-medical-facilities-and-practitioners"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Uruguay"]},{"k":"p","s":["Telephone: 911 (ambulance, fire, police)"]},{"k":"h","s":["Contact the police"]},{"k":"p","s":["If you need to report a crime, you can use a ",["Uruguayan government online form","https://www.gub.uy/tramites/recepcion-denuncias"]," (in Spanish)."]},{"k":"hs","s":["Requirement to attend police station"]},{"k":"p","s":["In some cases, there may be a requirement to visit a police station in person after reporting a crime online."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Uruguay"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Uruguay"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Uruguay"]," in Uruguay"]},{"k":"li","s":["dealing with a ",["death in Uruguay","https://www.gov.uk/government/publications/uruguay-guide-for-bereavement"]]},{"k":"li","s":["being ",["arrested or imprisoned in Uruguay","https://www.gov.uk/government/publications/uruguay-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/uruguay/british-embassy-montevideo"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/uruguay/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Uruguay","https://www.gov.uk/government/collections/overseas-business-risk-uruguay"]," on how to manage political, economic, and business security-related risks."]}],"chars":13721,"change":"New information about dual nationals returning to the UK (‘Entry requirements’ page)."},"https://theconversation.com/air-new-zealand-is-betting-on-christchurch-but-will-the-regions-benefit-as-well-296911":{"r":"conversation","at":"2026-11-22T19:15Z","sha":"04a9d777b26d4034103c86ba260c8ca0ab48573c9ce72b9883c1b0bb80487608","read":"https://theconversation.com/air-new-zealand-is-betting-on-christchurch-but-will-the-regions-benefit-as-well-296911","bytes":182122,"x":"fulltext v1","title":"Air New Zealand is betting on Christchurch. But will the regions benefit as well?","by":[{"n":"Ajai Jayathilakan","r":"Lecturer in Aviation Management, Te Kunenga ki Pūrehuroa – Massey University"}],"pub":"2026-11-22T17:47:32Z","mod":"","blocks":[{"k":"p","s":["When a Singapore-bound Boeing 787-9 Dreamliner took off from Christchurch Airport on October 28, it marked Air New Zealand’s return to non-stop long-haul flying from the South Island."]},{"k":"p","s":["The service is the first of ",["several international routes from Christchurch","https://www.airnewzealandnewsroom.com/press-release-2026-major-international-expansion-set-to-boost-christchurch-and-south-island-growth"]," being restored by the airline, with long-haul direct flights to Tokyo Narita scheduled to resume on November 28, followed by trans-Tasman services to Perth on November 30. A seasonal service to Bali ",["is also planned","https://www.airnewzealandnewsroom.com/press-release-2026-air-new-zealand-boosts-christchurch-connections-with-year-round-singapore-flights-and-new-bali-service"]," for winter 2027."]},{"k":"p","s":["Christchurch has long been considered New Zealand’s ",["second international gateway","https://www.christchurchairport.co.nz/about-us/who-we-are/facts-and-figures/"],", even if Auckland handles nearly three times ",["its total passenger volume","https://www.christchurchairport.co.nz/about-us/who-we-are/facts-and-figures/monthly-passenger-arrivals-and-departures/"],"."]},{"k":"p","s":["Much of the traffic in and out of the Garden City ",["is operated by international carriers","https://simpleflying.com/christchurch-airport-international-routes/"],". Singapore Airlines has served Christchurch for 40 years, Emirates operates a daily A380 service, and carriers from Asia, Australia and North America also fly into the city."]},{"k":"p","s":["Air New Zealand’s own long-haul presence in Christchurch has been minimal since 2020. Its decision to put its own aircraft behind the airport, at a scale not seen in years, signals a renewed commitment to the South Island."]},{"k":"p","s":["The airline has also confirmed its Singapore service will operate year-round, while a new partnership with Christchurch Airport aims to develop international connections over the longer term."]},{"k":"p","s":["This comes as the airport ",["prepares for its biggest international summer yet","https://www.christchurchairport.co.nz/about-us/who-we-are/media/2026/christchurch-airports-biggest-ever-international-summer-takes-flight/"],", with international seat capacity increasing 21% and long-haul capacity alone rising 54%."]},{"k":"p","s":["For South Island-bound travellers, the new services offer more opportunities to bypass Auckland altogether. For exporters, the Singapore route adds a direct cargo link into Asian markets."]},{"k":"p","s":["But whether the benefits will reach beyond Christchurch to smaller regional centres – where ",["flights remain limited and fares high","https://theconversation.com/nzs-regional-air-routes-are-under-pressure-is-more-government-intervention-the-answer-285135"]," – is another question."]},{"k":"h","s":["The regional connectivity problem"]},{"k":"p","s":["Christchurch ",["also serves as a hub for regional flights","https://www.christchurchairport.co.nz/travellers/flights/airlines/flight-routes/"],", with services connecting it to Queenstown, Dunedin, Nelson, Hokitika and Invercargill."]},{"k":"p","s":["Unlike foreign airlines serving Christchurch, Air New Zealand also operates the bulk of New Zealand’s domestic and regional network."]},{"k":"p","s":["While alliance and codeshare partners already offer single-ticket connections with through-checked baggage onto Air New Zealand’s regional flights, operating its own international aircraft gives the airline direct control over arrival and departure times."]},{"k":"p","s":["That makes it easier to align international schedules with onward domestic connections so travellers can bypass Auckland altogether – allowing a passenger arriving from Tokyo or Singapore, for instance, to transfer seamlessly onto a regional flight to Nelson."]},{"k":"p","s":["For international visitors, tighter connections could make smaller South Island destinations more accessible, while giving regional businesses better access to overseas markets."]},{"k":"p","s":["Whether this happens remains to be seen – particularly in light of concerns over regional fares sounded by some in the sector."]},{"k":"p","s":["In February, Billie Moore, then chief executive of industry association NZ Airports, ",["warned","https://nzairports.co.nz/news/air-nz-doesnt-see-a-competition-problem-regional-new-zealand-does/"]," about rising regional fares and falling seat numbers. “Regional New Zealand is living the reality of this every day,” she said."]},{"k":"p","s":["According to the association, Jetstar was set to increase the number of seats it offered on the Auckland to Christchurch route from roughly 491,000 in the first half of 2025 to 611,000 in the first half of 2026. Meanwhile, Air New Zealand’s fares on the route fell 16.9% between the first half of 2025 and the first half of 2026."]},{"k":"p","s":["In February 2026, Air New Zealand said it does not consider the lack of competition in New Zealand aviation to be a problem. This is challenged by NZ Airports, whose figures show a contrasting pattern."]},{"k":"p","s":["Comparing the first half of 2026 with the same period in 2025, the association reports that on routes where Jetstar provides competition, Air New Zealand’s fares fell by 4% and capacity increased by 0.6%. Over the same period on routes without Jetstar competition, fares rose by 4.2% while available seats fell by the same proportion."]},{"k":"p","s":["The economics of regional aviation help explain this divide. Airlines naturally concentrate capacity on routes with enough passengers to fill aircraft regularly, particularly where business and leisure demand is strong."]},{"k":"p","s":[["Regional flights in New Zealand","https://www.transport.govt.nz/assets/Uploads/Current-State-Description-Aviation-Action-Plan-2025.pdf"]," are expensive to operate because of relatively low demand, shorter routes and the higher per-passenger costs of smaller aircraft."]},{"k":"p","s":["Smaller centres face a different challenge. Their passenger numbers may be insufficient to support frequent services, even when those flights are important to local businesses, residents and tourism operators."]},{"k":"p","s":["A stronger Christchurch hub could generate additional demand for these routes, but that alone may not be enough to make them commercially viable."]},{"k":"h","s":["What could help the regions?"]},{"k":"p","s":["Several steps could help ensure Christchurch’s expansion benefits the wider regional network."]},{"k":"p","s":["Better coordination of international and regional services, including flight schedules, ",["through-ticketing","https://en.wiktionary.org/wiki/through-ticketing"]," and baggage transfers, would help ensure smaller centres share in the benefits."]},{"k":"p","s":["Targeted support for regional airports around Christchurch could help them capture the additional tourism and business demand a second gateway can generate."]},{"k":"p","s":[["A monitoring framework","https://nzairports.co.nz/news/nz-airports-sets-four-priorities-in-2026-election-manifesto/"],", as already proposed by NZ Airports, could track regional route capacity and fares alongside Christchurch’s headline growth figures, giving policymakers a clearer picture of how the wider network is performing."]},{"k":"p","s":["And for smaller routes that struggle to attract commercial services, a ",["public service obligation model","https://en.wikipedia.org/wiki/Public_service_obligation"]," – where governments subsidise airlines to maintain essential services – could help preserve connections that lack commercial viability in the first place."]},{"k":"p","s":["Christchurch’s long-haul expansion is a genuine milestone, and good news for the South Island."]},{"k":"p","s":["But without action from officials, airport operators and the aviation sector, New Zealand risks ending up with two thriving international gateways while smaller regional communities continue to miss out."]}],"chars":6010},"https://theconversation.com/soldats-francais-en-ukraine-un-pas-vers-la-cobelligerance-ou-simple-application-des-accords-existants-297240":{"r":"conversation","at":"2026-11-23T16:35Z","sha":"3ccc5af228a755333d93833505dc804c4d743f99f22dce93614e18ba9a348b0e","read":"https://theconversation.com/soldats-francais-en-ukraine-un-pas-vers-la-cobelligerance-ou-simple-application-des-accords-existants-297240","bytes":185368,"x":"fulltext v1","title":"Soldats français en Ukraine : un pas vers la cobelligérance ou simple application des accords existants ?","by":[{"n":"Cyrille Bret","r":"Géopoliticien, Sciences Po"}],"pub":"2026-11-23T16:04:07Z","mod":"","blocks":[{"k":"p","s":["L’ESSENTIEL"]},{"k":"li","s":["La révélation par RFI de la présence de militaires français en Ukraine (pour des missions de formation et de maintenance des équipements) a suscité de vives réactions à Moscou et à Paris."]},{"k":"li","s":["Le gouvernement français juge que cette présence découle naturellement d’accords connus de tous, mais cette vision est fortement contestée par plusieurs forces politiques."]},{"k":"li","s":["Que se produirait-il si ces soldats étaient visés par une frappe russe ? Répliqueraient-ils ? Jusqu’où l’appui de Paris à Kiev doit-il aller ? Ces questions s’invitent plus que jamais dans la campagne présidentielle française."]},{"k":"p","s":["Le 16 novembre dernier, une enquête de RFI a ",["révélé","https://www.rfi.fr/fr/europe/20261116-mission-volia-comment-l-arm%C3%A9e-fran%C3%A7aise-op%C3%A8re-en-ukraine"]," l’existence de l’opération Volia (« Volonté » en ukrainien) : au moins depuis l’été 2026, des militaires français, dont le nombre exact n’a pas été révélé, opèrent sur le sol ukrainien. Ils proviennent essentiellement des effectifs de la ",["mission Gerfaut déployée en Pologne depuis 2023","https://lignesdedefense.ouest-france.fr/loperation-de-formation-des-ukrainiens-en-pologne-baptisee-gerfaut/"]," dans le cadre de la mission d’assistance militaire de l’Union européenne en soutien à l’Ukraine ( ",["EUMAM-Ukraine)","https://www.consilium.europa.eu/fr/press/press-releases/2026/11/09/ukraine-council-extends-eu-military-assistance-mission-mandate-for-two-years/"],". Leur rôle n’est pas de participer aux combats contre les forces russes, mais de prodiguer des formations à leurs militaires ukrainiens et d’assurer la maintenance de matériels militaires français livrés à Kiev, notamment les canons Caesar et les avions de combat Mirage 2000."]},{"k":"p","s":["Les réactions ne se sont pas fait attendre."]},{"k":"p","s":["Du côté de Moscou, la porte-parole du ministère russe des affaires étrangères, ",["Maria Zakharova","https://mid.ru/en/foreign_policy/news/2164688/"],", y a trouvé la confirmation de la « cobelligérance » française avec l’Ukraine, autrement dit de la participation directe de la France à la guerre contre la Russie. Son ministre de tutelle Sergueï Lavrov a ",["abondé dans son sens","https://www.rfi.fr/fr/europe/20261117-soldats-fran%C3%A7ais-d%C3%A9ploy%C3%A9s-en-ukraine-moscou-y-voit-une-participation-directe-au-conflit"],"."]},{"k":"p","s":["Vladimir Poutine, qui avait ",["indiqué","https://www.franceinfo.fr/monde/europe/manifestations-en-ukraine/guerre-en-ukraine-vladimir-poutine-affirme-que-n-importe-quelle-force-militaire-occidentale-sera-une-cible-legitime-pour-l-armee-russe_7474501.html"]," par le passé que tout soldat étranger en arme et en uniforme sur le sol ukrainien serait considéré comme une cible légitime au regard du droit des conflits armés, n’a pas réagi publiquement, à ce stade, aux révélations de RFI sur la mission Volia. Mais le 12 novembre, quelques jours avant leur publication, il avait ",["réaffirmé","https://www.cctvplus.com/news/20261113/8508078.shtml"],", lors d’une rencontre au Kremlin avec Jared Kushner et Steve Witkoff, émissaires de Donald Trump que la présence de troupes étrangères en Ukraine était « absolument inacceptable » pour Moscou et constituait une menace pour la sécurité russe."]},{"k":"p","s":["En France aussi, l’information a soulevé de vives objections. Jean-Luc Mélenchon s’est, par exemple, inquiété du risque que la France soit désormais traitée par la Russie non plus seulement en rivale et soutien de Kiev, mais en ",["ennemie déclarée de la Fédération de Russie","https://rmc.bfmtv.com/actualites/politique/video-la-presence-de-soldats-francais-en-ukraine-fait-reagir-lfi_VN-202611180199.html"],"."]},{"k":"p","s":["Cette révélation a en tout cas le mérite de contraindre les pouvoirs publics français à préciser l’étendue, la nature et les perspectives de leur soutien militaire à l’Ukraine dans sa défense contre l’invasion illégale d’une partie de son territoire par la Russie."]},{"k":"h","s":["Un « secret de Polichinelle » ?"]},{"k":"p","s":["Pour minimiser la portée de ces révélations, les pouvoirs publics français, militaires comme civils, ont multiplié explications, distinguos et justifications."]},{"k":"p","s":["À ceux qui, à Moscou, considèrent que le déploiement de militaires français en Ukraine constitue un acte de guerre, le gouvernement Lecornu ",["réplique","https://www.diplomatie.gouv.fr/fr/presse-et-ressources/decouvrir-et-informer/actualites/france-5-entretien-de-jean-noel-barrot-0"]," qu’il s’agit bien de personnels en uniforme, mais exclusivement destinés à former les soldats ukrainiens, à réaliser la maintenance des matériels de guerre fournis à l’Ukraine, à assurer la logistique de la coopération militaire et à donner corps aux ",["coopérations technologiques officialisées en juin 2026 dans le cadre du salon Eurosatory","https://www.defense.gouv.fr/dga/actualites/france-lukraine-officialisent-laccord-partenariat-brave-france"],". La présence française, soulignent les autorités, serait faible en effectifs, très éloignée de la ligne de front et exclusivement consacrée à des missions n’impliquant aucun affrontement direct avec la Russie."]},{"k":"p","s":["Dans le même temps, à Paris, certains affirment que ",["l’article 35 de la Constitution française","https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000019241022"],", qui prévoit l’autorisation parlementaire pour toute déclaration de guerre, l’information du Parlement sur les interventions militaires à l’étranger et l’autorisation de prolonger celles-ci au-delà de quatre mois, a été ",["mis à mal","https://www.lemonde.fr/international/article/2026/11/19/guerre-en-ukraine-la-presence-de-soldats-francais-en-ukraine-fait-elle-de-paris-un-cobelligerant-contre-qui-la-russie-pourrait-riposter_6813225_3210.html"],"."]},{"k":"p","s":["Cette vision est partagée non seulement par La France insoumise (LFI), mais aussi par des représentants de la droite souverainiste, comme ",["Nicolas Dupont-Aignan","https://lanouvelletribune.info/2026/11/soldats-francais-en-ukraine-dupont-aignan-denonce-un-deploiement-sans-autorisation-prealable-du-parlement/"]," ou ",["Florian Philippot","https://x.com/f_philippot/status/2123059975056494972"],". Elle est également ",["exprimée","https://www.publicsenat.fr/actualites/parlementaire/soldats-francais-en-ukraine-je-proposerai-tres-rapidement-dauditionner-la-ministre-de-la-defense-annonce-cedric-perrin-le-president-de-la-commission-des-affaires-etrangeres"],", sous une forme moins virulente, par Cédric Perrin, le président Les Républicains (LR) de la commission des affaires étrangères du Sénat, et par la sénatrice socialiste Hélène Conway-Mouret, membre de cette même commission. À tous ceux-là, les autorités politiques ",["répondent","https://www.lefigaro.fr/international/guerre-en-ukraine-il-est-absurde-d-affirmer-que-les-soldats-francais-dans-le-pays-participent-directement-au-conflit-affirme-alice-rufo-20261117"]," que ce déploiement n’est pas régi par une « intentionnalité opérationnelle » et n’a pas de finalité combattante, et ne nécessitait donc pas de blanc-seing spécifique de la part du Parlement."]},{"k":"p","s":["Selon cette lecture, la révélation ne ferait que rendre public un « secret de Polichinelle » (formule d’ailleurs ",["employée par Maria Zakharova","https://www.aa.com.tr/fr/politique/zakharova-le-rapport-de-rfi-sur-la-pr%C3%A9sence-militaire-francaise-en-ukraine-n-est-ni-une-surprise-ni-une-r%C3%A9v%C3%A9lation-/4128358"],"), la présence de militaires français en Ukraine n’étant que la conséquence nécessaire du soutien capacitaire apporté par Paris à Kiev."]},{"k":"p","s":["Mais cette vision des choses n’est pas la seule possible : un autre choix aurait pu être fait, comme celui de confier les opérations de maintenance et de formation non à des soldats en uniforme déployés sur instructions de l’état-major, mais à des salariés de compagnies privées spécialisées françaises."]},{"k":"h","s":["La politique extérieure, c’est de la politique intérieure !"]},{"k":"p","s":["La révélation de RFI n’est pas aussi anodine qu’il y paraît. Certes, la lecture maximaliste de Moscou est de mauvaise foi dans la mesure où aucun élément, même de propagande russe, n’atteste la participation directe aux combats d’unités régulières des forces armées françaises, sous uniforme et commandement français. De jure, la France n’est pas en guerre contre la Russie, même si elle la sanctionne et même si elle aide activement les forces armées ukrainiennes – de la même façon, par exemple, que ",["son soutien actuel à l’Arabie saoudite frappée par l’Iran","https://www.franceinfo.fr/monde/proche-orient/tensions-entre-l-arabie-saoudite-et-l-iran/quatre-questions-sur-l-envoi-de-moyens-militaires-francais-pour-proteger-le-site-de-yanbu-en-arabie-saoudite_8212076.html"]," ne saurait être assimilé à une entrée en guerre de Paris contre Téhéran."]},{"k":"p","s":["Toutefois, l’opération Volia manifeste une inflexion de la posture française en Ukraine et à l’égard de la Russie. Dans une phase de négociations intenses et difficiles menées sur l’Ukraine par les puissances non européennes (États-Unis, Chine, Pakistan, etc.), il devient désormais plus compliqué pour Paris de se positionner en négociateur capable de proposer un plan de paix, un calendrier de discussion, des lieux d’échanges et ses « bons offices », et de porter la voix des Européens à la table des discussions."]},{"k":"p","s":["Et, à l’égard de la population française, engagée aujourd’hui dans un débat présidentiel critique, la politique ukrainienne de la France ne peut plus vraiment être présentée comme un simple appui. Si les soldats français s’engageaient progressivement dans d’autres missions réclamées par la protection de l’Ukraine (renseignement militaire, aide à la planification, défense anti-drones…), comment ne pas glisser graduellement vers des ripostes armées aux opérations russes dans la profondeur du territoire ukrainien ? Comment justifier l’inaction si, par malheur, les casernes où opèrent les instructeurs militaires français étaient touchées par des bombardements russes ?"]},{"k":"p","s":["Aujourd’hui plus qu’hier, la politique extérieure de la France, c’est de la politique intérieure : la posture à l’égard des opérations israéliennes à Gaza et contre l’Iran, l’attitude à l’égard de la Russie dans les discussions avec l’Ukraine et l’ampleur du réarmement français sont des sujets clivants pour les candidats et les électeurs. Il semblait déjà très probable que le dossier ukrainien serait largement évoqué durant la campagne présidentielle ; depuis les révélations sur l’existence de l’opération Volia, essentielles au débat public, c’est désormais une certitude."]}],"chars":7748},"https://theconversation.com/justice-is-elusive-for-the-rohingya-even-after-the-icjs-landmark-genocide-ruling-against-myanmar-297125":{"r":"conversation","at":"2026-11-24T20:25Z","sha":"b3dd71a8270b0df7d7b31abf2211eb3ab057044df1d87851290cc4e2992747c7","read":"https://theconversation.com/justice-is-elusive-for-the-rohingya-even-after-the-icjs-landmark-genocide-ruling-against-myanmar-297125","bytes":188076,"x":"fulltext v1","title":"Justice is elusive for the Rohingya even after the ICJ’s landmark genocide ruling against Myanmar","by":[{"n":"San Beauchemin","r":"Doctoral Researcher, School of Political Studies, L’Université d’Ottawa/University of Ottawa"}],"pub":"2026-11-24T16:49:44Z","mod":"","blocks":[{"k":"p","s":["By ",["nine votes to six, the International Court of Justice (ICJ) has ruled that Myanmar committed genocide","https://theconversation.com/a-seismic-icj-ruling-has-found-myanmar-responsible-for-genocide-but-will-it-help-the-rohingya-296700"]," against the Rohingya people in connection with its 2017 “clearance operations” in Rakhine State. The ruling is an ",["alarm bell for all states accused of genocide","https://www.chathamhouse.org/2026/11/icjs-myanmar-finding-shifts-dial-little-grounds-guilty-verdict-genocide-case"],"."]},{"k":"p","s":["The year 2017 was not the first Rohingya exodus from Myanmar: ",["in 1978 and again in 1991-92, hundreds of thousands of Rohingya poured into Bangladesh to escape state persecution","https://www.doctorswithoutborders.org/latest/timeline-rohingya-crisis"],". Many returned, and were forced to flee again when new violence erupted."]},{"k":"p","s":[["Today, more than 1.2 million Rohingya are in refugee camps in Bangladesh","https://www.unhcr.org/where-we-work/countries/bangladesh"]," without any concrete prospect to return to Myanmar. Most Rohingya want to return, but not without conditions that would ensure their safety. The most crucial condition is the guarantee of citizenship rights."]},{"k":"p","s":["Since Myanmar stripped the Rohingya of their citizenship in 1982, ",["they have been living under apartheid-like conditions","https://www.amnesty.org.uk/knowledge-hub/all-resources/myanmars-apartheid-against-the-rohingya/"],". Among many ",["discriminatory policies","https://doi.org/10.1177/2516606918764998"]," imposed on Rohingya life, the Rohingya faced restrictions on movement, education and health care while families ",["were restricted to a two-child limit.","https://www.hrw.org/news/2013/05/28/burma-revoke-two-child-policy-rohingya"]," Returning to Myanmar just to face the same conditions of life is not an option for many Rohingya."]},{"k":"h","s":["The repatriation conundrum"]},{"k":"p","s":["It’s unlikely, however, that Myanmar will agree to grant citizenship to the Rohingya."]},{"k":"p","s":["Since the ",["2021 coup d'état","https://www.bbc.com/news/world-asia-55882489"]," that ousted leader Aung San Suu Kyi and her National League for Democracy, the military has ",["had sole control of the government","https://doi.org/10.31752/idea.2022.16"],"."]},{"k":"p","s":["Earlier this year, Min Aung Hlaing, ",["the architect of the Rohingya genocide","https://www.fortifyrights.org/mya-inv-oped-2026-04-10/"]," who had been commander-in-chief of the Myanmar Forces since 2011, stepped down from his role and was subsequently ",["elected president by a military-dominated parliament","https://www.aljazeera.com/news/2026/4/3/myanmars-coup-leader-elected-president-by-pro-military-parliament"],". This makes the prospect of a safe and dignified repatriation of the Rohingya to Myanmar a near impossibility."]},{"k":"p","s":["The Myanmar military and government aren’t the only entities complicating the return of the Rohingya. Since late 2023, vast swaths of Rakhine state, where most Rohingya resided until 2017, ",["have been under control of the Arakan army.","https://acleddata.com/report/state-nation-arakan-armys-ascent-post-coup-myanmar"]]},{"k":"p","s":[["The army is the largest and most powerful non-state armed group in the country","https://jamestown.org/arakan-army-becomes-most-effective-insurgent-force-in-myanmar/"]," and it ",["is vying for the independence of the Arakan region","https://arakanstudies.org/ibr/24/03/ibr_03-July_24.html"],", where Rakhine is located. The Arakan army is openly hostile to the Rohingya, and those residing in the territory it controls are ",["facing many of the same restrictions that were previously imposed by the state.","https://www.hrw.org/news/2025/07/28/myanmar-arakan-army-oppresses-rohingya-muslims"]]},{"k":"h","s":["The enforcement deficit"]},{"k":"p","s":["The ICJ established Myanmar’s responsibility for the genocide, and consequently ordered it to provide reparations and compensation, with details still to be decided."]},{"k":"p","s":["But, in practice, there is little the court can do to compel Myanmar to take accountability and pursue justice if it refuses to do so. ",["The ICJ has no independent enforcement mechanism","https://lop.parl.ca/en/researchpublications/202503e"],"; it only relies on states’ willingness to obey international law."]},{"k":"p","s":["Only the United Nations Security Council could decide to take coercive action against Myanmar, but ",["China and Russia, which both hold veto power, are likely to oppose it.","https://www.cfr.org/articles/with-genocide-ruling-justice-finally-descends-upon-myanmar-and-the-rohingya"]]},{"k":"p","s":["The two states have provided Min Aung Hlaing’s regime with ",["political, diplomatic and military","https://edition.cnn.com/2023/05/18/world/un-myanmar-report-military-junta-deadly-arms-sales-russia-china-intl-hnk"]," support over the years. Each also has its own issues with international human rights law, namely Russia’s war in Ukraine and ",["China’s treatment of the Uyghurs","https://www.humanrightsresearch.org/post/persecution-of-uyghurs-in-xinjiang-torture-crimes-against-humanity-and-genocide"],"."]},{"k":"h","s":["How the ruling might help the Rohingya"]},{"k":"p","s":["The ICJ ruling has brought much-needed attention to the plight of the Rohingya. Renewed interest in the Rohingya crisis is expected to draw donations that could help alleviate some of the more pressing needs."]},{"k":"p","s":["Funding for the refugee camps has dwindled in the aftermath of the ",["COVID-19 pandemic","https://www.tbsnews.net/rohingya-crisis/funding-rohingyas-dwindles-amid-pandemic-146758"]," and ",["the dismantlement of the U.S. Agency for International Development (USAID)","https://www.theguardian.com/global-development/2025/dec/01/bangladesh-rohingya-refugees-aid-health-funding-cuts-infants-malnutrition"],". Currently, the ",["Rohingya in Bangladesh only receive US$7-$12 per person per month","https://www.wfp.org/news/wfp-introduces-needs-based-food-assistance-approach-rohingya-refugees-bangladesh"]," in food assistance."]},{"k":"p","s":["Read more: ",["Thousands are feared dead in Myanmar’s quake. Trump’s USAID cuts will cause even more unnecessary deaths","https://theconversation.com/thousands-are-feared-dead-in-myanmars-quake-trumps-usaid-cuts-will-cause-even-more-unnecessary-deaths-253403"]]},{"k":"p","s":["Combined with the lack of income-generating opportunities, the cuts to food rations ",["are frequently identified by refugees as the most severe challenge they face in the camps.","https://reliefweb.int/report/bangladesh/ration-cuts-loom-rohingya-families-worlds-largest-refugee-settlement-say-theyll-be-forced-send-children-away-dangerous-journeys"]]},{"k":"p","s":["More attention could also result in stronger political pressure, not just on Myanmar but also on its regional partners. Malaysia, for example, ",["began deporting refugees back to Myanmar in September 2026","https://www.aljazeera.com/news/2026/10/5/nearly-1500-migrants-arrive-in-myanmar-from-malaysia-despite-un-warnings"],"."]},{"k":"p","s":["Since the government continues to deny access to international agencies for the refugees, ",["including the United Nations High Commissioner for Refugees","https://news.un.org/en/story/2026/09/1168491"],", it could not be verified whether these returns were voluntary, as Malaysia claimed."]},{"k":"p","s":["It’s unlikely the Rohingya, who make up the majority of Myanmar refugees in Malaysia, are returning of their own free will. International pressure could force Malaysia to stop the deportations and avoid causing further harm to its already vulnerable Rohingya refugee community."]},{"k":"h","s":["Not ‘illegal immigrants’"]},{"k":"p","s":["Finally, the most immediate benefit of the ruling is that, for the first time, there is a formal recognition of the Rohingya as a distinct people. The ruling directly contradicts Myanmar’s assertions that the Rohingya are ",["“illegal immigrants from Bangladesh”","https://amnesty.org.nz/who-are-rohingya-and-why-are-they-fleeing-myanmar/"]," who have no legitimate claim to rights and land in Rakhine."]},{"k":"p","s":["The ICJ ruling clearly affirms that the atrocities the Rohingya have suffered are indeed genocide, and while it doesn’t guarantee justice for the Rohingya, it’s a necessary precondition that opens the path to restorative justice."]}],"chars":5334},"https://theconversation.com/lebanon-facing-uncertain-future-as-un-peacekeepers-prepare-to-depart-297693":{"r":"conversation","at":"2026-11-27T15:24Z","sha":"5166f6a01c6a569e6e278ba98dfbd444d15feca4232284856a6d1787213ec734","read":"https://theconversation.com/lebanon-facing-uncertain-future-as-un-peacekeepers-prepare-to-depart-297693","bytes":178330,"x":"fulltext v1","title":"Lebanon facing uncertain future as UN peacekeepers prepare to depart","by":[{"n":"Ray Murphy","r":"Emeritus Professor at the Irish Centre for Human Rights, University of Galway"}],"pub":"2026-11-27T14:24:10Z","mod":"","blocks":[{"k":"p","s":["Lebanon is facing an uncertain future, with the UN peacekeeping mission in the south of the country drawing to a close in December after nearly 50 years. The current situation is the most serious to confront Lebanon since my time serving there as a UN peacekeeper in 1982."]},{"k":"p","s":["The withdrawal of the UN Interim Force in ",["Lebanon","https://theconversation.com/topics/lebanon-5458"]," (Unifil) is taking place against a backdrop of volatility. Conflict between the Israeli military and ",["Hezbollah","https://theconversation.com/topics/hezbollah-4783"],", a Lebanese armed group, has escalated in the past few years. This has caused repeated displacement, destruction of homes and infrastructure, civilian deaths and damage to agricultural land across the country."]},{"k":"p","s":["From March 2026 to June, when a ceasefire in Lebanon was signed, at least 3,783 people were ",["killed","https://www.reuters.com/world/middle-east/costs-lebanon-latest-israel-hezbollah-war-2026-06-16/"]," and 11,699 wounded in the conflict, according to the country’s health ministry. The death toll included 247 children, 363 women and 133 healthcare workers. At least 28 Israeli soldiers have been killed in Lebanon in the latest war, while four Israeli civilians have been killed in Hezbollah attacks."]},{"k":"p","s":["Despite the ceasefire, Israeli forces continue military operations in southern Lebanon. These include ",["airstrikes and shelling","https://www.timesofisrael.com/air-force-strikes-hezbollah-rockets-launchers-in-eastern-lebanon-idf/"]," beyond the so-called security zone they reestablished earlier in 2026. Recent weeks have also ",["seen extensive destruction","https://acleddata.com/expert-comment/what-do-israels-strikes-lebanons-jenta-town-reveal-about-hezbollahs-military"]," of Lebanese civilian infrastructure and villages by the Israeli military."]},{"k":"p","s":["The plan moving forward is for the Lebanese state to be the sole provider of security in the south of the country. But this is neither practical nor realistic. The Lebanese armed forces have neither the capacity or the capability to fulfil such a role."]},{"k":"h","s":["New security framework"]},{"k":"p","s":["The decision to end Unifil’s mandate was made by the UN security council in August 2025. It followed ",["intense political pressure","https://usun.usmission.gov/explanation-of-vote-on-the-un-security-council-mandate-renewal-of-the-un-interim-force-in-lebanon-unifil/"]," from the US and Israel, who have argued the peacekeeping force has failed its mission by allowing Hezbollah to build military infrastructure near the Israeli border."]},{"k":"p","s":[["UN Security Council Resolution 1701","https://news.un.org/en/story/2024/10/1155221"],", which provides the basis for the current Unifil operations, mandated that southern Lebanon should be free of armed personnel and weapons other than those belonging to the Lebanese armed forces and the over 7,000 UN peacekeepers."]},{"k":"p","s":["A ",["new security framework","https://www.state.gov/releases/office-of-the-spokesman/2026/06/trilateral-framework-between-the-united-states-of-america-the-state-of-israel-and-the-republic-of-lebanon"]," was agreed in June 2026 following talks between Lebanon, Israel and the US. Lebanon and Israel committed to a reciprocal and sequenced process whereby the Lebanese armed forces will restore effective sovereign authority over all Lebanese territory."]},{"k":"p","s":["The Israel Defense Forces will then progressively redeploy out of Lebanese territory, pending the verified disarmament of non-state armed groups and dismantlement of their associated infrastructure."]},{"k":"p","s":["However, this remains a distant prospect. Hezbollah has ",["repeatedly rejected calls","https://www.fdd.org/analysis/to-disarm-hezbollah-washington-must-target-its-political-protectors/"]," to disarm while Israel maintains a military presence in Lebanese territory."]},{"k":"p","s":["Lebanon, along with some EU states, have sought agreement for a new peacekeeping force or presence from the US and other UN security council members. A range of options have been floated since the decision to end Unifil’s mandate, including a French proposal for a ",["multinational European force","https://www.washingtonpost.com/world/2026/11/20/europeans-seek-replace-un-peacekeeping-force-lebanon/"]," that would operate alongside the Lebanese armed forces."]},{"k":"p","s":["But none of these proposals have been acceptable to the US and Israel. The Israelis want any future role for an international force to include more than monitoring and reporting what is happening on the ground – the primary tasks performed by Unifil."]},{"k":"p","s":["They insist such a force should be operationally integrated with Israel’s declared objectives of disarming Hezbollah and dismantling its infrastructure."]},{"k":"p","s":["Nevertheless, the international community should not abandon Lebanon. One possible interim mechanism to fill the void left by Unifil’s withdrawal is to strengthen the presence in Lebanon of the UN Truce Supervision Organization (Untso) and its observer group."]},{"k":"p","s":["Untso was the ",["first peacekeeping mission","https://peacekeeping.un.org/en/factsheet/untso"]," to be established by the UN in 1948. Its military observers remain in the Middle East to monitor ceasefires, supervise armistice agreements and prevent isolated incidents from escalating. They also assist other UN peacekeeping operations in the region, including in Lebanon."]},{"k":"p","s":["This interim measure would leave at least some UN presence on the ground in Lebanon to monitor the various parties to the conflict and report on what is happening there. Untso will remain in Lebanon after Unifil’s withdrawal. But pressure would need to be brought to bear on Israel and Hezbollah to facilitate a strengthened presence."]},{"k":"h","s":["Consequences of Unifil withdrawal"]},{"k":"p","s":["The end of Unfil’s mandate poses a major security problem for Lebanon. Since 1978, Unifil has played a major stabilising and diplomatic role in Lebanon that is often not acknowledged. It has provided essential support to the Lebanese army and has historically facilitated negotiations between Israel and Lebanon."]},{"k":"p","s":["Unifil’s withdrawal also threatens the loss of much-needed services in the south. UN peacekeepers have ",["provided safe passage","https://peacekeeping.un.org/en/news/peacekeepers-step-up-support-as-families-return-to-south-lebanon"]," for humanitarian aid convoys and have helped restore damaged services such as healthcare and water."]},{"k":"p","s":["The central issue now is what happens to civilian protection, independent monitoring and international oversight after Unifil leaves. Its exit comes at a time when access to southern Lebanon is already severely hampered by the scale of the destruction, unexploded ordnance and landmines."]},{"k":"p","s":["Displaced Lebanese civilians must be allowed to return home and further destruction of civilian infrastructure must be prevented. But whether the new security framework can guarantee this is far from clear."]}],"chars":5541}};
